from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

import heapq
from itertools import combinations


def _route(minimum_duration, exact):
    def solve(data):
        required = data.get("required", [])
        bits = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        initial_mask = bits.get(source, 0)
        coupons = data["coupons"]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start = (source, initial_mask, 0)
        distances = {start: data["start"]}
        queue = [(data["start"], source, initial_mask, 0)]
        while queue:
            time, node, mask, spent = heapq.heappop(queue)
            state = (node, mask, spent)
            if distances.get(state) != time:
                continue
            if (node == data["target"] and mask == full and
                    (spent == coupons if exact else True)):
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                next_mask = mask | bits.get(edge["v"], 0)
                durations = [(edge["duration"], spent)]
                if spent < coupons:
                    reduced = max(minimum_duration,
                                  edge["duration"] - edge.get("discount", 0))
                    durations.append((reduced, spent + 1))
                for duration, next_spent in durations:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_mask, next_spent)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, edge["v"],
                                               next_mask, next_spent))
        return {"arrival": None}
    return solve


def _ledger(data):
    events = data["events"]
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(events):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    half_up = data["rounding"] == "half_up"

    def rounded(numerator):
        if half_up:
            numerator += 5000
        return numerator // 10000

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _resolver(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    best_vector = None
    best = None

    # Each package is either absent or assigned one of its versions.
    choices = []
    for name in names:
        versions = sorted({row["version"] for row in packages[name]})
        choices.append([None] + versions)

    def check(assignment):
        installed = {name for name, version in assignment.items()
                     if version is not None}
        for name, bounds in data.get("roots", {}).items():
            version = assignment[name]
            if version is None or not bounds[0] <= version <= bounds[1]:
                return False
        for name in installed:
            version = assignment[name]
            if version in blocked.get(name, []) or (name in pins and
                                                       version != pins[name]):
                return False

        rows = {}
        for name in installed:
            rows[name] = next(row for row in packages[name]
                              if row["version"] == assignment[name])

        graph = {name: [] for name in installed}
        closure = set(data.get("roots", {}))
        pending = list(closure)
        while pending:
            name = pending.pop()
            if name not in installed:
                return False
            for dep in rows[name].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                version = assignment[target]
                if version is None or not dep["min"] <= version <= dep["max"]:
                    return False
                graph[name].append(target)
                if target not in closure:
                    closure.add(target)
                    pending.append(target)
        if closure != installed:
            return False

        active, finished = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in graph[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        return all(visit(name) for name in installed)

    def enumerate_assignments(index, assignment):
        nonlocal best_vector, best
        if index == len(names):
            if not check(assignment):
                return
            vector = tuple(-1 if assignment[name] is None else assignment[name]
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best = {name: assignment[name] for name in names
                        if assignment[name] is not None}
            return
        name = names[index]
        for version in choices[index]:
            assignment[name] = version
            enumerate_assignments(index + 1, assignment)
        del assignment[name]

    enumerate_assignments(0, {})
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _intervals(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    if not mandatory.issubset({job["id"] for job in jobs}) or len(mandatory) > k:
        return {"error": "impossible"}
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for selected in combinations(jobs, k):
        ids = tuple(sorted(job["id"] for job in selected))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        points = sorted({job["start"] for job in selected})
        if any(sum(job["start"] <= point < job["end"] for job in selected) > 2
               for point in points):
            continue
        value = sum(job["value"] for job in selected)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


SOLVERS = {
    "component_01": _route(1, True),
    "component_02": _route(2, False),
    "component_03": _route(2, True),
    "component_04": _route(1, False),
    "component_05": _route(1, True),
    "component_06": _ledger,
    "component_07": _resolver,
    "component_08": _intervals,
}
